/**
 * Expo config plugin: sign Android release builds with the owner's keystore (research.md R17).
 *
 * `android/` is regenerated by `expo prebuild`, so the signing config is injected here instead of
 * being edited by hand. The keystore path and passwords come from Gradle properties, normally the
 * user-level `~/.gradle/gradle.properties` (never committed):
 *
 *   RIFFLECT_STORE_FILE=C:/Users/<you>/keys/rifflect-release.jks
 *   RIFFLECT_KEY_ALIAS=rifflect
 *   RIFFLECT_STORE_PASSWORD=...
 *   RIFFLECT_KEY_PASSWORD=...
 *
 * If any property is missing, release builds FAIL with a clear message. They never fall back to the
 * debug key, because an APK signed with a different key can't update the installed app without an
 * uninstall, and uninstalling deletes every take.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// rifflect-release-signing';

const SIGNING_BLOCK = `
    ${MARKER}
    def rifflectProps = ['RIFFLECT_STORE_FILE', 'RIFFLECT_KEY_ALIAS', 'RIFFLECT_STORE_PASSWORD', 'RIFFLECT_KEY_PASSWORD']
    def rifflectSigningReady = rifflectProps.every { project.hasProperty(it) }
    signingConfigs {
        rifflectRelease {
            if (rifflectSigningReady) {
                storeFile file(project.property('RIFFLECT_STORE_FILE'))
                storePassword project.property('RIFFLECT_STORE_PASSWORD')
                keyAlias project.property('RIFFLECT_KEY_ALIAS')
                keyPassword project.property('RIFFLECT_KEY_PASSWORD')
            }
        }
    }
    gradle.taskGraph.whenReady { graph ->
        def wantsRelease = graph.allTasks.any { it.name.toLowerCase().contains('release') }
        if (wantsRelease && !rifflectSigningReady) {
            throw new GradleException(
                "Rifflect release signing is not configured. Add " + rifflectProps.join(', ') +
                " to ~/.gradle/gradle.properties (see README.md). Refusing to sign with the debug key."
            )
        }
    }
`;

function addSigning(buildGradle) {
  if (buildGradle.includes(MARKER)) return buildGradle;

  // 1. Insert our signingConfigs + guard at the start of the `android { ... }` block.
  const androidOpen = /android\s*\{/;
  if (!androidOpen.test(buildGradle)) {
    throw new Error('withReleaseSigning: could not find the android { } block in app/build.gradle');
  }
  let out = buildGradle.replace(androidOpen, (m) => `${m}\n${SIGNING_BLOCK}`);

  // 2. Point the release build type at our signing config (the template uses the debug key).
  const releaseType = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig\s+signingConfigs\.debug/;
  if (releaseType.test(out)) {
    out = out.replace(releaseType, '$1signingConfig signingConfigs.rifflectRelease');
  } else {
    const releaseOpen = /(buildTypes\s*\{[\s\S]*?release\s*\{)/;
    if (!releaseOpen.test(out)) {
      throw new Error('withReleaseSigning: could not find buildTypes.release in app/build.gradle');
    }
    out = out.replace(releaseOpen, '$1\n            signingConfig signingConfigs.rifflectRelease');
  }
  return out;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('withReleaseSigning: only Groovy app/build.gradle is supported');
    }
    cfg.modResults.contents = addSigning(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.addSigning = addSigning;
